INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Sicherheitssystem immer zertifiziert sein muss?', 2, '[{"text": "Nein", "correct": true, "because": "Freiwillig möglich"}, {"text": "Ja", "correct": false, "because": "Nur bei Normen wie ISO 27001"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Schritt ist der erste, um Datenrisiken zu managen?', 3, '[{"text": "Risiken identifizieren", "correct": true, "because": "Basis für Schutz"}, {"text": "Richtlinien schreiben", "correct": false, "because": "Späterer Schritt"}, {"text": "Software kaufen", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben hat ein System zum Schutz von Informationen?', 5, '[{"text": "Risiken bewerten", "correct": true, "because": "Erkennt Gefahren"}, {"text": "Richtlinien setzen", "correct": true, "because": "Definiert Verhalten"}, {"text": "Audits planen", "correct": true, "because": "Prüft Einhaltung"}, {"text": "Farben wählen", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Es schützt sensible Daten. b) Es ist nur für IT-Abteilungen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ganzes Unternehmen betrifft"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich ein Sicherheitssystem einrichte?', 4, '[{"text": "Risikoanalyse", "correct": false, "because": "Kern der Planung"}, {"text": "Richtlinien", "correct": false, "because": "Leitfaden nötig"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Schutzsystem nur für große Firmen ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Für alle Größen"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode hilft, Sicherheitslücken zu finden?', 3, '[{"text": "Risikoanalyse", "correct": true, "because": "Erkennt Schwachstellen"}, {"text": "Design", "correct": false, "because": "Kein Sicherheitsaspekt"}, {"text": "Hardwarekauf", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Sicherheitssystem?', 5, '[{"text": "Datenschutz", "correct": true, "because": "Sichert Informationen"}, {"text": "Risikominimierung", "correct": true, "because": "Reduziert Gefahren"}, {"text": "Compliance", "correct": true, "because": "Erfüllt Vorgaben"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) Audits Teil davon sind und b) es nur Technik betrifft. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Prozesse betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um ein Schutzsystem aufzubauen?', 4, '[{"text": "Risikoanalyse", "correct": false, "because": "Erkennt Gefahren"}, {"text": "Richtlinien", "correct": false, "because": "Steuert Verhalten"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Schutzsystem nur für IT?', 2, '[{"text": "Nein", "correct": true, "because": "Unternehmensweit"}, {"text": "Ja", "correct": false, "because": "Alle Bereiche"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte helfen bei der Risikobewertung?', 4, '[{"text": "Gefahren erkennen", "correct": true, "because": "Erster Schritt"}, {"text": "Maßnahmen planen", "correct": true, "because": "Reduziert Risiken"}, {"text": "Farben wählen", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Schutzsystem keine Audits braucht. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Prüfung nötig"}, {"text": "Ja", "correct": false, "because": "Kontrolle essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Sicherheitssystem?', 3, '[{"text": "Daten schützen", "correct": true, "because": "Vertraulichkeit sichern"}, {"text": "Design verbessern", "correct": false, "because": "Sekundär"}, {"text": "Kosten erhöhen", "correct": false, "because": "Nicht Zweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Es reduziert Risiken. b) Es ist nur für Technik.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Prozesse"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Führung bei einem Schutzsystem?', 4, '[{"text": "Verantwortung tragen", "correct": true, "because": "Leitet Prozess"}, {"text": "Design wählen", "correct": false, "because": "Irrelevant"}, {"text": "Hardware kaufen", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Schutzsystem Schulungen braucht?', 2, '[{"text": "Ja", "correct": true, "because": "Sensibilisiert Mitarbeiter"}, {"text": "Nein", "correct": false, "because": "Wissen nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen ein Sicherheitssystem effektiv?', 5, '[{"text": "Risikomanagement", "correct": true, "because": "Reduziert Gefahren"}, {"text": "Richtlinien", "correct": true, "because": "Steuert Verhalten"}, {"text": "Audits", "correct": true, "because": "Prüft Einhaltung"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Schutzsystem nur für große Firmen?', 3, '[{"text": "Nein", "correct": true, "because": "Für alle Größen"}, {"text": "Ja", "correct": false, "because": "Flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einem Sicherheitssystem?', 4, '[{"text": "Risikoanalyse nach Cyberangriff", "correct": true, "because": "Bewertet Gefahren"}, {"text": "Webdesign", "correct": false, "because": "Andere Aufgabe"}, {"text": "Hardwarekauf", "correct": false, "because": "Technische Rolle"}]');
